const TASK_OWNERSHIP_CALIBRATION_RECOMMENDED_SAMPLES = 30

function selectedReviewBinomialCalibration(successes: number, failures: number): {
  reviewed: number
  observedRate: number | null
  lower95: number | null
  upper95: number | null
  recommendedMinimum: number
  remainingToRecommended: number
  readyForTrend: boolean
  interpretation: string
} {
  const correct = Math.max(0, Math.floor(Number(successes) || 0))
  const incorrect = Math.max(0, Math.floor(Number(failures) || 0))
  const reviewed = correct + incorrect
  if (!reviewed) {
    return {
      reviewed: 0,
      observedRate: null,
      lower95: null,
      upper95: null,
      recommendedMinimum: TASK_OWNERSHIP_CALIBRATION_RECOMMENDED_SAMPLES,
      remainingToRecommended: TASK_OWNERSHIP_CALIBRATION_RECOMMENDED_SAMPLES,
      readyForTrend: false,
      interpretation: 'selected_review_interval_not_population_accuracy'
    }
  }
  const observedRate = correct / reviewed
  const z = 1.959963984540054
  const denominator = 1 + (z * z) / reviewed
  const centre = (observedRate + (z * z) / (2 * reviewed)) / denominator
  const margin = z * Math.sqrt(
    (observedRate * (1 - observedRate) / reviewed) + (z * z) / (4 * reviewed * reviewed)
  ) / denominator
  const rounded = (value: number) => Math.round(value * 10_000) / 10_000
  return {
    reviewed,
    observedRate: rounded(observedRate),
    lower95: rounded(Math.max(0, centre - margin)),
    upper95: rounded(Math.min(1, centre + margin)),
    recommendedMinimum: TASK_OWNERSHIP_CALIBRATION_RECOMMENDED_SAMPLES,
    remainingToRecommended: Math.max(
      0,
      TASK_OWNERSHIP_CALIBRATION_RECOMMENDED_SAMPLES - reviewed
    ),
    readyForTrend: reviewed >= TASK_OWNERSHIP_CALIBRATION_RECOMMENDED_SAMPLES,
    interpretation: 'selected_review_interval_not_population_accuracy'
  }
}

function searchEvidenceScopeSql(
  alias: string,
  options: Pick<MemorySearchOptions, 'sourceIds' | 'sessionId' | 'sessionName' | 'from' | 'to'>
): { sql: string; parameters: Array<string | number> } {
  const clauses: string[] = []
  const parameters: Array<string | number> = []
  const sourceIds = [...new Set((options.sourceIds || [])
    .map(value => String(value).trim().toLowerCase()).filter(Boolean))]
  if (sourceIds.length) {
    clauses.push(`LOWER(${alias}.source_id) IN (${sourceIds.map(() => '?').join(',')})`)
    parameters.push(...sourceIds)
  }
  const sessions = options.sessionId
    ? [...new Set([options.sessionId, options.sessionName]
        .map(value => String(value || '').trim()).filter(Boolean))]
    : []
  if (sessions.length) {
    clauses.push(`${alias}.session_id IN (${sessions.map(() => '?').join(',')})`)
    parameters.push(...sessions)
  }
  const boundary = (value: string | undefined, endOfDay: boolean): number | null => {
    const text = String(value || '').trim()
    if (!text) return null
    const normalized = /^\d{4}-\d{2}-\d{2}$/.test(text)
      ? `${text}T${endOfDay ? '23:59:59.999' : '00:00:00.000'}+08:00`
      : text
    const timestamp = Date.parse(normalized)
    return Number.isFinite(timestamp) ? Math.floor(timestamp / 1000) : null
  }
  const from = boundary(options.from, false)
  const to = boundary(options.to, true)
  if (from !== null) {
    clauses.push(`${alias}.timestamp>=?`)
    parameters.push(from)
  }
  if (to !== null) {
    clauses.push(`${alias}.timestamp<=?`)
    parameters.push(to)
  }
  return {
    sql: clauses.length ? clauses.join(' AND ') : '1=1',
    parameters
  }
}

function searchDocumentSupportsFactsSql(
  options: MemorySearchOptions = {},
  alias = 'd'
): { sql: string; parameters: Array<string | number> } {
  const branches = [
    { type: 'claim', foreignKey: 'claim_id', table: 'evidence' },
    { type: 'relation', foreignKey: 'relation_id', table: 'evidence' },
    { type: 'event', foreignKey: 'event_id', table: 'evidence' }
  ]
  const parameters: Array<string | number> = []
  const structured = branches.map(branch => {
    const scope = searchEvidenceScopeSql('support', options)
    parameters.push(...scope.parameters)
    return `(${alias}.document_type='${branch.type}'
      AND COALESCE(json_extract(${alias}.metadata_json,'$.status'),'')='confirmed'
      AND EXISTS (SELECT 1 FROM ${branch.table} support
        WHERE support.${branch.foreignKey}=${alias}.source_id
          AND COALESCE(support.evidence_role,'direct')!='contradiction'
          AND ${scope.sql}))`
  })
  const genericScope = searchEvidenceScopeSql('support', options)
  parameters.push(...genericScope.parameters)
  return {
    sql: `(
    ${structured.join('\n    OR ')}
    OR (${alias}.document_type NOT IN ('entity','claim','relation','event')
      AND EXISTS (SELECT 1 FROM search_document_evidence support
        WHERE support.document_id=${alias}.id
          AND ${genericScope.sql}))
  )`,
    parameters
  }
}

function searchDocumentHasContradictionSql(
  options: MemorySearchOptions = {},
  alias = 'd'
): { sql: string; parameters: Array<string | number> } {
  const branches = [
    { type: 'claim', foreignKey: 'claim_id' },
    { type: 'relation', foreignKey: 'relation_id' },
    { type: 'event', foreignKey: 'event_id' }
  ]
  const parameters: Array<string | number> = []
  const sql = branches.map(branch => {
    const scope = searchEvidenceScopeSql('conflict', options)
    parameters.push(...scope.parameters)
    return `(${alias}.document_type='${branch.type}'
      AND EXISTS (SELECT 1 FROM evidence conflict
        WHERE conflict.${branch.foreignKey}=${alias}.source_id
          AND conflict.evidence_role='contradiction'
          AND ${scope.sql}))`
  }).join('\n    OR ')
  return { sql: `(${sql})`, parameters }
}

function searchDocumentEvidenceStrengthSql(
  strength: 'direct' | 'indirect_only',
  options: MemorySearchOptions = {},
  alias = 'd'
): { sql: string; parameters: Array<string | number> } {
  const branches = [
    { type: 'claim', foreignKey: 'claim_id' },
    { type: 'relation', foreignKey: 'relation_id' },
    { type: 'event', foreignKey: 'event_id' }
  ]
  const parameters: Array<string | number> = []
  const sql = branches.map(branch => {
    const selectedScope = searchEvidenceScopeSql('strength', options)
    parameters.push(...selectedScope.parameters)
    const selectedRole = strength === 'direct'
      ? `COALESCE(strength.evidence_role,'direct')='direct'`
      : `strength.evidence_role='indirect'`
    let directExclusion = ''
    if (strength === 'indirect_only') {
      const directScope = searchEvidenceScopeSql('direct_strength', options)
      parameters.push(...directScope.parameters)
      directExclusion = `
        AND NOT EXISTS (SELECT 1 FROM evidence direct_strength
          WHERE direct_strength.${branch.foreignKey}=${alias}.source_id
            AND COALESCE(direct_strength.evidence_role,'direct')='direct'
            AND ${directScope.sql})`
    }
    return `(${alias}.document_type='${branch.type}'
      AND EXISTS (SELECT 1 FROM evidence strength
        WHERE strength.${branch.foreignKey}=${alias}.source_id
          AND ${selectedRole}
          AND ${selectedScope.sql})
      ${directExclusion})`
  }).join('\n    OR ')
  return { sql: `(${sql})`, parameters }
}

function searchDocumentSupportingSourceCountSql(
  options: MemorySearchOptions = {},
  alias = 'd'
): { sql: string; parameters: Array<string | number> } {
  const branches = [
    { type: 'claim', foreignKey: 'claim_id', evidenceAlias: 'claim_breadth' },
    { type: 'relation', foreignKey: 'relation_id', evidenceAlias: 'relation_breadth' },
    { type: 'event', foreignKey: 'event_id', evidenceAlias: 'event_breadth' }
  ]
  const parameters: Array<string | number> = []
  const structured = branches.map(branch => {
    const scope = searchEvidenceScopeSql(branch.evidenceAlias, options)
    parameters.push(...scope.parameters)
    return `WHEN ${alias}.document_type='${branch.type}' THEN (
      SELECT COUNT(DISTINCT LOWER(COALESCE(${branch.evidenceAlias}.source_id,'legacy')))
      FROM evidence ${branch.evidenceAlias}
      WHERE ${branch.evidenceAlias}.${branch.foreignKey}=${alias}.source_id
        AND COALESCE(${branch.evidenceAlias}.evidence_role,'direct')!='contradiction'
        AND ${scope.sql}
    )`
  }).join('\n    ')
  const genericScope = searchEvidenceScopeSql('generic_breadth', options)
  parameters.push(...genericScope.parameters)
  return {
    sql: `(CASE
    ${structured}
    WHEN ${alias}.document_type!='entity' THEN (
      SELECT COUNT(DISTINCT LOWER(COALESCE(generic_breadth.source_id,'legacy')))
      FROM search_document_evidence generic_breadth
      WHERE generic_breadth.document_id=${alias}.id
        AND ${genericScope.sql}
    )
    ELSE 0 END)`,
    parameters
  }
}

function relationSearchText(
  subjectName: unknown,
  predicate: unknown,
  objectName: unknown,
  directionExplanation: unknown
): string {
  const base = [subjectName, predicate, objectName]
    .map(value => String(value || '').trim())
    .filter(Boolean)
    .join(' ')
  const explanation = String(directionExplanation || '').trim()
  return [base, explanation && !base.includes(explanation) ? explanation : '']
    .filter(Boolean)
    .join(' ')
    .slice(0, 2000)
}

function assistantAnswerReviewMutationToken(input: {
  messageId: unknown
  stateKey: unknown
  reviewState: unknown
  latestDecisionId: unknown
}): string {
  return createHash('sha256').update(JSON.stringify({
    version: 'assistant-answer-review-mutation-v1',
    messageId: String(input.messageId || ''),
    stateKey: String(input.stateKey || ''),
    reviewState: String(input.reviewState || ''),
    latestDecisionId: Number(input.latestDecisionId || 0)
  })).digest('hex')
}

function sanitizeMemoryDeletionImpact(value: unknown): {
  evidence: number
  related: number
  searchDocuments: number
  assistantMessages: number
} {
  let parsed: any = {}
  try {
    parsed = typeof value === 'string' ? JSON.parse(value || '{}') : value || {}
  } catch {}
  const boundedCount = (input: unknown) =>
    Math.max(0, Math.min(1_000_000_000, Math.floor(Number(input) || 0)))
  return {
    evidence: boundedCount(parsed.evidence),
    related: boundedCount(parsed.related),
    searchDocuments: boundedCount(parsed.searchDocuments),
    assistantMessages: boundedCount(parsed.assistantMessages)
  }
}

function evidenceSourceId(
  evidence: any,
  fallback = ''
): string {
  const explicit = String((evidence?.source_id ?? evidence?.sourceId ?? fallback) || '').trim()
  if (explicit) return explicit.slice(0, 120)
  const sessionId = String(evidence?.session_id ?? evidence?.sessionId ?? '').trim()
  const dataSource = sessionId.match(/^data-source:([^:]+)/)?.[1]
  if (dataSource) return dataSource.slice(0, 120)
  const messageId = String(evidence?.message_id ?? evidence?.messageId ?? '').trim()
  const embeddedSource = messageId.match(/^(wechat|documents|calendar|mail):/)?.[1]
  return embeddedSource || 'legacy'
}

function canonicalTaskEvidenceRows(rows: any[][]): any[][] {
  const unique = new Map<string, any[]>()
  for (const row of rows) {
    const normalized = [
      String(row?.[0] || ''),
      String(row?.[1] || ''),
      String(row?.[2] || ''),
      Number(row?.[3] || 0),
      String(row?.[4] || ''),
      String(row?.[5] || '').slice(0, 2000)
    ]
    const identity = JSON.stringify(normalized.slice(0, 3))
    const existing = unique.get(identity)
    if (!existing) {
      unique.set(identity, normalized)
      continue
    }
    unique.set(identity, [
      existing[0],
      existing[1],
      existing[2],
      Math.max(Number(existing[3] || 0), Number(normalized[3] || 0)),
      String(normalized[4] || '') || String(existing[4] || ''),
      String(normalized[5] || '') || String(existing[5] || '')
    ])
  }
  return [...unique.values()]
    .sort((left, right) => JSON.stringify(left).localeCompare(JSON.stringify(right)))
}

function taskEvidenceContentFingerprint(rows: any[][]): string {
  return createHash('sha256')
    .update(JSON.stringify(canonicalTaskEvidenceRows(rows)))
    .digest('hex')
}

function taskOwnershipVersionScope(value: any): {
  policyVersion: string
  promptVersion: string
  schemaVersion: string
  model: string
  sourceKind: 'wechat' | 'documents' | 'legacy'
} {
  const bounded = (input: unknown, fallback: string) =>
    String(input || '').trim().slice(0, 120) || fallback
  return {
    policyVersion: bounded(value?.ownershipPolicyVersion, 'legacy-unknown-policy'),
    promptVersion: bounded(value?.ownershipPromptVersion, 'legacy-unknown-prompt'),
    schemaVersion: bounded(value?.ownershipSchemaVersion, 'legacy-unknown-schema'),
    model: bounded(value?.ownershipModel, 'legacy-unknown-model'),
    sourceKind: value?.ownershipSourceKind === 'wechat' || value?.ownershipSourceKind === 'documents'
      ? value.ownershipSourceKind
      : 'legacy'
  }
}

function taskOwnershipVersionKey(value: any): string {
  return createHash('sha256')
    .update(JSON.stringify(taskOwnershipVersionScope(value)))
    .digest('hex')
}

function compactTaskReviewSnapshot(value: unknown): any {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {}
  const {
    evidence: _evidence,
    sourceMessageIds: _sourceMessageIds,
    source_message_ids: _sourceMessageIdsLegacy,
    ...snapshot
  } = value as Record<string, unknown>
  return snapshot
}

function parseJsonObject(value: unknown): any {
  try {
    const parsed = JSON.parse(String(value || '{}'))
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {}
  } catch {
    return {}
  }
}

function parseJsonArray(value: unknown): any[] {
  try {
    const parsed = JSON.parse(String(value || '[]'))
    return Array.isArray(parsed) ? parsed : []
  } catch {
    return []
  }
}

function hydrateTaskReviewSnapshot(taskJson: unknown, evidenceJson: unknown): any {
  const task = parseJsonObject(taskJson)
  const evidence = parseJsonArray(evidenceJson)
  if (!task.id && !task.title) return task
  return {
    ...task,
    evidence,
    sourceMessageIds: [...new Set(evidence.map(item =>
      String(item?.messageId ?? item?.message_id ?? '').trim()).filter(Boolean))]
  }
}

const RECOVERY_PAYLOAD_CODEC = 'gzip-json-v1'

function compressRecoveryPayload(payload: Record<string, string>): {
  blob: Buffer
  originalBytes: number
  sha256: string
} {
  const serialized = JSON.stringify(payload)
  const blob = gzipSync(Buffer.from(serialized), { level: 9 })
  return {
    blob,
    originalBytes: Buffer.byteLength(serialized),
    sha256: createHash('sha256').update(blob).digest('hex')
  }
}

function decodeRecoveryPayload(row: any, keys: string[]): {
  payload: Record<string, string>
  recoveredFromBackup: boolean
  repairBackupFromPrimary: boolean
  repairHash: boolean
  verifiedBlob: Buffer | null
} {
  if (String(row?.payload_codec || '') !== RECOVERY_PAYLOAD_CODEC) {
    return {
      payload: Object.fromEntries(keys.map(key => [key, String(row?.[key] ?? '')])),
      recoveredFromBackup: false,
      repairBackupFromPrimary: false,
      repairHash: false,
      verifiedBlob: null
    }
  }
  const expectedHash = String(row?.payload_sha256 || '').trim()
  const candidates = [
    { blob: row.payload_blob, backup: false },
    { blob: row.payload_backup_blob, backup: true }
  ]
  const valid: Array<{
    blob: Buffer
    backup: boolean
    sha256: string
    parsed: Record<string, unknown>
  }> = []
  for (const candidate of candidates) {
    if (!candidate.blob) continue
    const blob = Buffer.from(candidate.blob)
    try {
      const parsed = JSON.parse(gunzipSync(blob).toString('utf8'))
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        throw new Error('压缩恢复载荷不是对象')
      }
      valid.push({
        blob,
        backup: candidate.backup,
        sha256: createHash('sha256').update(blob).digest('hex'),
        parsed
      })
    } catch {}
  }
  if (!valid.length) throw new Error('压缩恢复载荷两份副本均不可读取')
  const matchingHash = expectedHash
    ? valid.filter(candidate => candidate.sha256 === expectedHash)
    : []
  let chosen = matchingHash.find(candidate => !candidate.backup) || matchingHash[0]
  if (!chosen) {
    const distinctHashes = new Set(valid.map(candidate => candidate.sha256))
    if (valid.length !== 1 && distinctHashes.size !== 1) {
      throw new Error('压缩恢复载荷副本不一致且无法确定可信版本')
    }
    chosen = valid.find(candidate => !candidate.backup) || valid[0]
  }
  const primary = row?.payload_blob ? Buffer.from(row.payload_blob) : null
  const backup = row?.payload_backup_blob ? Buffer.from(row.payload_backup_blob) : null
  return {
    payload: Object.fromEntries(keys.map(key => [
      key, String(chosen.parsed[key] ?? '')
    ])),
    recoveredFromBackup: !primary?.equals(chosen.blob),
    repairBackupFromPrimary: !backup?.equals(chosen.blob),
    repairHash: expectedHash !== chosen.sha256,
    verifiedBlob: chosen.blob
  }
}

